/**
 * Shader des lignes de balayage.
 *
 * ## L'idee mathematique
 *
 * Tout l'ecran cathodique tient dans des fonctions periodiques du seul axe
 * vertical : les lignes sont un sinus de y a haute frequence, la barre qui
 * roule est la partie fractionnaire de y decalee par le temps, et le grain
 * est un hachage du pixel rejoue par paliers de temps — discret, parce qu'un
 * tirage par image scintillerait au lieu de granuler. Une vignette referme le
 * tout.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond du tube.
 * - `uColorB` — la teinte du phosphore.
 * - `uColorC` — la teinte de la barre qui roule.
 * - `uSpeed` — vitesse de la barre.
 * - `uLines` — nombre de lignes sur la hauteur.
 * - `uFlicker` — part du grain anime.
 */
export const SCANLINES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uLines;
uniform float uFlicker;

// Nombre pseudo-aleatoire : projection sur une direction arbitraire, sinus
// amplifie, partie fractionnaire.
float tubeHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float t = uTime;

  // Les lignes : un sinus de y, eleve au carre pour creuser les interlignes
  // sans durcir les cretes.
  float ligne = 0.5 + 0.5 * sin(vUv.y * max(uLines, 1.0) * 6.28318);
  ligne = 0.35 + 0.65 * ligne * ligne;

  // La barre qui roule : la partie fractionnaire de y decalee par le temps
  // fait boucler la descente sans aucun test.
  float roulement = fract(vUv.y + t * uSpeed * 0.2);
  float barre = smoothstep(0.0, 0.12, roulement) * smoothstep(0.30, 0.12, roulement);

  // Le grain : un hachage du pixel rejoue par paliers de temps. Discret —
  // le palier tient l'image quelques centiemes — parce qu'un tirage par
  // image scintille au lieu de granuler.
  float palier = floor(t * 18.0);
  float grain = (tubeHash(floor(vUv * uResolution * 0.5) + palier) - 0.5) * uFlicker * 0.35;

  vec3 colour = mix(uColorA, uColorB, ligne * (0.75 + grain));
  colour = mix(colour, uColorC, barre * 0.30);

  // Vignette : les coins d'un tube sont plus sombres que son centre.
  vec2 ecart = (vUv - 0.5) * vec2(aspect, 1.0);
  colour *= 1.0 - smoothstep(0.35, 0.85, length(ecart)) * 0.55;

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Lignes de balayage : un ecran cathodique, sa barre qui roule et son grain.
 *
 * ## Le principe
 *
 * Tout tient dans des fonctions periodiques du seul axe vertical : un sinus pour les lignes, une partie fractionnaire decalee par le temps pour la barre.
 *
 * Le grain est rejoue par paliers de temps, jamais par image — un tirage par image scintille au lieu de granuler.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur — les recopier ici en ferait autant
 * de versions a maintenir qu'il y a de fonds.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface — il n'en
 * accorde qu'une par backend — et sous mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { SCANLINES_FRAGMENT } from './scanlines.shader.js'

/** Ce que l'echappatoire recoit. */
export interface ScanlinesControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface ScanlinesOwnProps {
  /** Vitesse de la barre qui roule. @defaultValue 0.5 */
  speed?: number
  /** Nombre de lignes sur la hauteur. @defaultValue 90 */
  lines?: number
  /** Part du grain anime. @defaultValue 0.4 */
  flicker?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<ScanlinesControls>
}

/** Toutes les proprietes. */
export type ScanlinesProps = Customisable<ScanlinesOwnProps>

/** Tokens employes par defaut : le tube, le phosphore, la barre. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-green-400',
  '--o-palette-emerald-200',
] as const

/** Repli par defaut : une teinte figee, dans les memes tons. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Lignes de balayage.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Scanlines className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Scanlines({
  speed = 0.5,
  lines = 90,
  flicker = 0.4,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: ScanlinesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: SCANLINES_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uLines: lines, uFlicker: flicker },
    name: 'scanlines',
    // Le grain est la seule valeur recalculee a chaque palier de temps : sur
    // un ecran dont la densite a ete plafonnee, c'est aussi ce qui fourmille
    // le plus. Il est donc le reglage borne.
    degrade: (quality) => ({
      uFlicker: quality === 'low' ? Math.min(flicker, 0.15) : flicker,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
